'use client';

import Link from 'next/link';
import Image from 'next/image';
import { useEffect, useRef, useState } from 'react';
import { motion, MotionConfig, useReducedMotion, useScroll, useTransform } from 'motion/react';

import type { Locale, PortfolioContent } from '@/data/portfolio';
import { getHeroDescriptionMotion, getRevealMotion, subtleHover, subtleTap } from '@/lib/animation';
import { MagneticButton } from './magnetic-button';
import { ThemeProvider } from './theme-provider';
import { ThemeToggle } from './theme-toggle';
import { SpotlightCard } from './spotlight-card';
import { SplitText } from './split-text';
import { Aurora } from './aurora';

type Props = { locale: Locale; content: PortfolioContent };

export function Portfolio({ locale, content }: Props) {
  const reducedMotion = useReducedMotion();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [hasScrolled, setHasScrolled] = useState(false);
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const { scrollYProgress } = useScroll();
  const heroArtY = useTransform(scrollYProgress, [0, 0.25], [0, -36]);
  const otherLocale: Locale = locale === 'pt' ? 'en' : 'pt';
  const otherLanguage = locale === 'pt' ? 'EN' : 'PT';
  const reveal = getRevealMotion(Boolean(reducedMotion));
  const heroDescription = getHeroDescriptionMotion(Boolean(reducedMotion));
  const heroArtAnimation = reducedMotion ? { opacity: 1 } : { opacity: 1, scale: 1, rotate: 0 };

  useEffect(() => {
    const closeMenuOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && isMenuOpen) {
        setIsMenuOpen(false);
        menuButtonRef.current?.focus();
      }
    };

    window.addEventListener('keydown', closeMenuOnEscape);
    return () => window.removeEventListener('keydown', closeMenuOnEscape);
  }, [isMenuOpen]);

  useEffect(() => {
    const updateHeaderState = () => setHasScrolled(window.scrollY > 12);
    updateHeaderState();
    window.addEventListener('scroll', updateHeaderState, { passive: true });
    return () => window.removeEventListener('scroll', updateHeaderState);
  }, []);

  const closeMenu = () => setIsMenuOpen(false);

  return (
    <ThemeProvider>
      <MotionConfig reducedMotion="user">
      <main className="site-shell">
        <div className="noise" aria-hidden="true" />

        <header className={`topbar${hasScrolled ? ' is-scrolled' : ''}`}>
          <Link href={`/${locale}`} className="mark" aria-label="Guilherme Oliveira home">GO<span>.</span></Link>
          <nav id="primary-navigation" className={`primary-nav${isMenuOpen ? ' is-open' : ''}`} aria-label="Primary navigation">
            <a href="#about" onClick={closeMenu}>{content.navigation.about}</a>
            <a href="#experience" onClick={closeMenu}>{content.navigation.experience}</a>
            <a href="#work" onClick={closeMenu}>{content.navigation.work}</a>
            <a href="#services" onClick={closeMenu}>{content.navigation.services}</a>
            <a href="#contact" onClick={closeMenu}>{content.navigation.contact}</a>
          </nav>
          <div className="header-actions">
            <button
              ref={menuButtonRef}
              className="menu-button"
              type="button"
              aria-expanded={isMenuOpen}
              aria-controls="primary-navigation"
              aria-label={isMenuOpen ? (locale === 'pt' ? 'Fechar menu de navegação' : 'Close navigation menu') : (locale === 'pt' ? 'Abrir menu de navegação' : 'Open navigation menu')}
              onClick={() => setIsMenuOpen((isOpen) => !isOpen)}
            >
              <span aria-hidden="true" />
              <span aria-hidden="true" />
            </button>
            <Link href={`/${otherLocale}`} className="language-link" lang={otherLocale}>{otherLanguage}</Link>
            <ThemeToggle />
          </div>
        </header>

        <section className="hero" aria-labelledby="hero-heading">
          <motion.div
            className="hero-aurora"
            animate={reducedMotion ? undefined : { scale: [1, 1.12, 1], x: [-60, 60, -60], y: [22, -28, 22] }}
            transition={{ duration: 11, repeat: Infinity, ease: 'easeInOut' }}
          >
            <Aurora colorStops={['#080808', '#7a7a76', '#f2f2ed']} amplitude={1.42} blend={0.78} speed={0.82} paused={Boolean(reducedMotion)} />
          </motion.div>
          <motion.div className="hero-copy" initial={reducedMotion ? false : { opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
            <p className="eyebrow"><span className="status-dot" />{content.hero.eyebrow}</p>
            <SplitText id="hero-heading" text={content.hero.heading} reducedMotion={Boolean(reducedMotion)} />
            <motion.p className="hero-description" {...heroDescription}>{content.hero.description}</motion.p>
            <div className="hero-actions">
              <MagneticButton className="button button-solid" href="#experience" reducedMotion={Boolean(reducedMotion)}>{content.hero.primaryAction}<span>↘</span></MagneticButton>
              <MagneticButton className="button button-ghost" href="#contact" reducedMotion={Boolean(reducedMotion)}>{content.hero.secondaryAction}<span>↗</span></MagneticButton>
            </div>
          </motion.div>
          <motion.div className="hero-art" initial={reducedMotion ? false : { opacity: 0, scale: 0.96, rotate: -2 }} animate={heroArtAnimation} transition={{ duration: 0.75, ease: [0.22, 1, 0.36, 1] }} style={reducedMotion ? undefined : { y: heroArtY }}>
            <div className="art-frame portrait-frame">
              <Image src="/guilherme-oliveira-portrait.jpeg" alt="Guilherme Oliveira" width={1448} height={1080} priority sizes="(max-width: 760px) 68vw, min(31vw, 410px)" className="portrait-image" />
            </div>
            <p>{content.name}<br />— 2026</p>
          </motion.div>
        </section>

        <section className="section about" id="about">
          <motion.div {...reveal} className="section-intro"><p className="section-label">{content.about.label}</p><h2>{content.about.title}</h2></motion.div>
          <motion.div {...reveal} className="about-content"><p>{content.about.body}</p><div className="metrics">{content.about.metrics.map((metric) => <div key={metric.label}><strong>{metric.value}</strong><span>{metric.label}</span></div>)}</div></motion.div>
        </section>

        <section className="section work" id="work">
          <motion.div {...reveal} className="section-intro"><p className="section-label">{content.work.label}</p><h2>{content.work.title}</h2><p className="section-description">{content.work.intro}</p></motion.div>
          <div className="project-list">{content.projects.map((project, index) => (
            <SpotlightCard className="project-spotlight" spotlightColor="rgba(127, 127, 127, 0.2)" disabled={Boolean(reducedMotion)} key={project.number}>
            <motion.article {...reveal} transition={{ ...reveal.transition, delay: index * 0.08 }} whileHover={reducedMotion ? undefined : subtleHover} className="project">
              <div className={`project-visual visual-${index + 1}`}><span>{project.number}</span><motion.div className="visual-mark" animate={reducedMotion ? undefined : { rotate: index === 0 ? [-14, -4, -14] : [0, 8, 0], scale: [1, 1.06, 1] }} transition={{ duration: 7, repeat: Infinity, ease: 'easeInOut' }}>{index === 0 ? 'A' : index === 1 ? 'M' : 'F'}</motion.div><p>{project.year}</p></div>
              <div className="project-details"><p className="project-category">{project.category}</p><h3>{project.title}</h3><p>{project.description}</p><div className="project-footer"><ul>{project.technologies.map((technology) => <li key={technology}>{technology}</li>)}</ul><a href={project.href}>{project.actionLabel}<span>↗</span></a></div></div>
            </motion.article>
            </SpotlightCard>
          ))}</div>
        </section>

        <section className="section services" id="services">
          <motion.div {...reveal} className="section-intro"><p className="section-label">{content.services.label}</p><h2>{content.services.title}</h2></motion.div>
          <div className="service-list">{content.services.items.map((service) => <motion.article {...reveal} whileHover={{ x: reducedMotion ? 0 : 6 }} className="service" key={service.number}><span>{service.number}</span><h3>{service.title}</h3><p>{service.description}</p><b>↘</b></motion.article>)}</div>
        </section>

        <section className="section experience" id="experience">
          <motion.div {...reveal} className="section-intro"><p className="section-label">{content.experience.label}</p><h2>{content.experience.title}</h2></motion.div>
          <div className="timeline">{content.experience.items.map((item) => <motion.article {...reveal} key={item.period}><p>{item.period}</p><div><h3>{item.role}<span>@ {item.company}</span></h3><p>{item.description}</p></div></motion.article>)}</div>
        </section>

        <section className="contact" id="contact">
          <motion.div {...reveal}><p className="section-label">{content.contact.label}</p><h2>{content.contact.title}</h2><p className="contact-copy">{content.contact.description}</p><div className="contact-details"><a className="contact-email" href={`mailto:${content.contact.email}`}>{content.contact.email}<span>↗</span></a><span className="contact-separator" aria-hidden="true">·</span><a className="contact-phone" href={`tel:${content.contact.phone.replace(/\D/g, '')}`}>{content.contact.phone}</a></div></motion.div>
          <div className="contact-links"><p>{content.contact.socialLabel}</p><motion.a href="https://github.com/glrm079" target="_blank" rel="noreferrer" whileHover={{ x: reducedMotion ? 0 : 4 }} whileTap={subtleTap}>GitHub <span>↗</span></motion.a><motion.a href="https://www.linkedin.com/in/guilherme-oliveira-96583023a/" target="_blank" rel="noreferrer" whileHover={{ x: reducedMotion ? 0 : 4 }} whileTap={subtleTap}>LinkedIn <span>↗</span></motion.a></div>
        </section>

        <footer><span>© {new Date().getFullYear()}</span><span>{content.footer}</span><a href="#hero-heading">↑</a></footer>
      </main>
      </MotionConfig>
    </ThemeProvider>
  );
}
